trait OrderService { def place(req: OrderRequest): Task[Long] }

final class OrderServiceLive(orders: OrderRepo, tx: Transactor) extends OrderService {
  def place(req: OrderRequest): Task[Long] = tx.transact(orders.insert(req))
}

object OrderService {
  val live: ZLayer[OrderRepo & Transactor, Nothing, OrderService] =
    ZLayer(for { o <- ZIO.service[OrderRepo]; t <- ZIO.service[Transactor] } yield OrderServiceLive(o, t))
}
